{
  "name": "@nk070281sjv/cli",
  "version": "3.0.65",
  "description": "OpenCode-only OCR CLI with process-agent review orchestration",
  "type": "module",
  "bin": {
    "ocr": "./dist/index.js"
  },
  "exports": {
    ".": {
      "types": "./src/index.ts",
      "source": "./src/index.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "assets"
  ],
  "keywords": [
    "code-review",
    "ai",
    "cli",
    "ocr",
    "opencode"
  ],
  "repository": {
    "type": "git",
    "url": "https://git.kbyte.app/ecom/developer-platform/opencode-review.git",
    "directory": "packages/cli"
  },
  "license": "Apache-2.0",
  "author": "Yurko",
  "engines": {
    "node": ">=22.5.0"
  },
  "dependencies": {
    "@inquirer/prompts": "^7.2.0",
    "chalk": "^5.4.1",
    "chokidar": "^4.0.3",
    "commander": "^13.0.0",
    "cross-spawn": "^7.0.6",
    "log-update": "^7.0.2",
    "mdast-util-from-markdown": "^2.0.3",
    "mdast-util-to-markdown": "^2.1.2",
    "ora": "^8.1.1",
    "yaml": "^2.8.3"
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@types/mdast": "^4.0.4",
    "@open-code-review/config": "0.0.0",
    "@open-code-review/persistence": "0.0.0",
    "@open-code-review/platform": "0.0.0"
  }
}
